def book_weights(book, prices, cash=0.0):
    total = cash
    for ticker, qty in book.items():
        if ticker not in prices:
            return None
        total = total + qty * prices[ticker]
    if total == 0:
        return None
    weights = {}
    for ticker, qty in book.items():
        weights[ticker] = qty * prices[ticker] / total
    return weights
